#include "../ring3_common.hpp"
static constexpr u32 W=620,H=430; static u32*pix; static char*doc; static u64 len,cap,events,win; static bool dirty=true;
static bool reserve(u64 need){if(need<=cap)return true;u64 nc=cap?cap:4096;while(nc<need){u64 z=nc*2;if(z<=nc)return false;nc=z;}char*n=(char*)(u64)sc(SYS_ALLOC,nc);if(!n)return false;for(u64 i=0;i<len;i++)n[i]=doc[i];n[len]=0;if(doc)sc(SYS_FREE,(u64)doc);doc=n;cap=nc;return true;}
static void key(char c){if(c=='\b'){if(len)doc[--len]=0;}else if(c=='\r')c='\n';if(c!='\b'&&reserve(len+2)){doc[len++]=c;doc[len]=0;}dirty=true;}
static void draw(){fill(pix,W*H,0x00eef2f5);rect(pix,W,H,0,0,W,44,0x002a5f9e);text(pix,W,H,16,14,"DAVIS WRITER  RING 3",0x00ffffff,2);rect(pix,W,H,12,54,W-24,32,0x00d8e4ef);text(pix,W,H,22,66,"FILE  EDIT  FORMAT  REVIEW  INSERT",0x00182030,1);rect(pix,W,H,20,98,W-40,H-116,0x00ffffff);u64 start=0,lines=0;for(u64 i=len;i>0;i--){if(doc[i-1]=='\n'&&++lines>=18){start=i;break;}}i32 x=32,y=112;for(u64 i=start;i<len&&y<H-22;i++){char c=doc[i];if(c=='\n'||x>W-44){x=32;y+=16;if(c=='\n')continue;}char z[2]={c,0};text(pix,W,H,x,y,z,0x00182030,1);x+=6;}rect(pix,W,H,x,y,2,9,0x001b64b2);text(pix,W,H,22,H-14,"PROCESS ISOLATED FROM KERNEL",0x00485465,1);sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,150,120);if(!win)sc(0,2);reserve(4096);const char*hello="Writer is now a Ring 3 application.\nType here. A Writer fault is isolated from the kernel.";for(u64 i=0;hello[i];i++)doc[len++]=hello[i];doc[len]=0;for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){auto*k=(KeyEv*)m.payload;key((char)k->codepoint);}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
